{
  "root": "main_stack",
  "state": {
    "otc_medications": [
      {
        "type": "Antihistamines",
        "purpose": "Oral antihistamines (e.g., loratadine, fexofenadine, cetirizine) reduce sneezing, itching, and runny nose. Nasal antihistamine sprays are also available."
      },
      {
        "type": "Nasal Corticosteroids",
        "purpose": "Sprays (e.g., fluticasone, budesonide) are highly effective for nasal congestion, sneezing, and runny nose, often taken daily during allergy season."
      },
      {
        "type": "Decongestants",
        "purpose": "Oral decongestants (e.g., pseudoephedrine, phenylephrine) or nasal decongestant sprays (e.g., oxymetazoline) can relieve stuffiness, but nasal sprays should only be used for a few days to avoid rebound congestion."
      },
      {
        "type": "Eye Drops",
        "purpose": "Antihistamine eye drops can alleviate itchy and watery eyes."
      }
    ],
    "prescription_medications": [
      {
        "type": "Leukotriene Modifiers",
        "purpose": "Oral medications (e.g., montelukast) can help with nasal congestion and asthma symptoms."
      },
      {
        "type": "Immunotherapy (Allergy Shots/Tablets)",
        "purpose": "For persistent and severe allergies, a doctor may recommend allergy shots or sublingual tablets to desensitize the immune system to specific allergens over time."
      }
    ]
  },
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md",
        "padding": 16
      },
      "children": [
        "title_h2",
        "intro_card",
        "symptoms_section",
        "treatment_section",
        "context_section",
        "resources_section"
      ]
    },
    "title_h2": {
      "type": "Text",
      "props": {
        "text": "Seasonal Allergies in Adults: Symptoms and Treatments",
        "variant": "h2"
      },
      "children": []
    },
    "intro_card": {
      "type": "Card",
      "props": {},
      "children": [
        "intro_stack"
      ]
    },
    "intro_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "intro_icon",
        "intro_text"
      ]
    },
    "intro_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000402_01_1_cloud-sun.svg"
      },
      "children": []
    },
    "intro_text": {
      "type": "Text",
      "props": {
        "text": "Seasonal allergies, often called hay fever or allergic rhinitis, can develop or worsen in adulthood, even for individuals who haven't experienced them previously. They occur when your immune system overreacts to airborne particles like pollen from trees, grasses, or weeds, which are prevalent during specific times of the year."
      },
      "children": []
    },
    "symptoms_section": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "symptoms_h3",
        "symptoms_intro_card",
        "nasal_symptoms_card",
        "eye_symptoms_card",
        "throat_symptoms_card"
      ]
    },
    "symptoms_h3": {
      "type": "Text",
      "props": {
        "text": "Recognizing Seasonal Allergy Symptoms",
        "variant": "h3"
      },
      "children": []
    },
    "symptoms_intro_card": {
      "type": "Card",
      "props": {},
      "children": [
        "symptoms_intro_stack"
      ]
    },
    "symptoms_intro_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "symptoms_intro_icon",
        "symptoms_intro_text"
      ]
    },
    "symptoms_intro_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000402_01_2_bandaid.svg"
      },
      "children": []
    },
    "symptoms_intro_text": {
      "type": "Text",
      "props": {
        "text": "Symptoms typically affect the nose, eyes, and throat, and can range from mild to severe, impacting daily life."
      },
      "children": []
    },
    "nasal_symptoms_card": {
      "type": "Card",
      "props": {},
      "children": [
        "nasal_symptoms_label",
        "nasal_symptoms_list"
      ]
    },
    "nasal_symptoms_label": {
      "type": "Text",
      "props": {
        "text": "Nasal Symptoms:",
        "variant": "label"
      },
      "children": []
    },
    "nasal_symptoms_list": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "nasal_symptom_1",
        "nasal_symptom_2",
        "nasal_symptom_3",
        "nasal_symptom_4"
      ]
    },
    "nasal_symptom_1": {
      "type": "Text",
      "props": {
        "text": "• Sneezing, often in bursts"
      },
      "children": []
    },
    "nasal_symptom_2": {
      "type": "Text",
      "props": {
        "text": "• Runny nose with clear, watery discharge"
      },
      "children": []
    },
    "nasal_symptom_3": {
      "type": "Text",
      "props": {
        "text": "• Stuffy or congested nose"
      },
      "children": []
    },
    "nasal_symptom_4": {
      "type": "Text",
      "props": {
        "text": "• Itchy nose, palate, or throat"
      },
      "children": []
    },
    "eye_symptoms_card": {
      "type": "Card",
      "props": {},
      "children": [
        "eye_symptoms_label",
        "eye_symptoms_list"
      ]
    },
    "eye_symptoms_label": {
      "type": "Text",
      "props": {
        "text": "Eye Symptoms:",
        "variant": "label"
      },
      "children": []
    },
    "eye_symptoms_list": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "eye_symptom_1",
        "eye_symptom_2",
        "eye_symptom_3"
      ]
    },
    "eye_symptom_1": {
      "type": "Text",
      "props": {
        "text": "• Itchy, watery, or red eyes"
      },
      "children": []
    },
    "eye_symptom_2": {
      "type": "Text",
      "props": {
        "text": "• Swollen eyelids"
      },
      "children": []
    },
    "eye_symptom_3": {
      "type": "Text",
      "props": {
        "text": "• Scratchy or sore throat"
      },
      "children": []
    },
    "throat_symptoms_card": {
      "type": "Card",
      "props": {},
      "children": [
        "throat_symptoms_label",
        "throat_symptoms_list"
      ]
    },
    "throat_symptoms_label": {
      "type": "Text",
      "props": {
        "text": "Throat and Other Symptoms:",
        "variant": "label"
      },
      "children": []
