      "children": [
        "throat_symptom_1",
        "throat_symptom_2",
        "throat_symptom_3",
        "throat_symptom_4"
      ]
    },
    "throat_symptom_1": {
      "type": "Text",
      "props": {
        "text": "• Coughing, sometimes due to post-nasal drip"
      },
      "children": []
    },
    "throat_symptom_2": {
      "type": "Text",
      "props": {
        "text": "• Fatigue or irritability due to poor sleep"
      },
      "children": []
    },
    "throat_symptom_3": {
      "type": "Text",
      "props": {
        "text": "• Headaches or sinus pressure"
      },
      "children": []
    },
    "throat_symptom_4": {
      "type": "Text",
      "props": {
        "text": "• Scratchy or sore throat"
      },
      "children": []
    },
