      },
      "children": [
        "treatment_h3",
        "treatment_intro_card",
        "otc_meds_card",
        "prescription_meds_card",
        "lifestyle_card"
      ]
    },
    "treatment_h3": {
      "type": "Text",
      "props": {
        "text": "Effective Management and Treatment Options",
        "variant": "h3"
      },
      "children": []
    },
