      },
      "children": []
    },
    "otc_meds_table": {
      "type": "Table",
      "props": {
        "columns": [
          {
            "key": "type",
            "label": "Medication Type"
          },
          {
            "key": "purpose",
            "label": "Purpose"
          }
        ],
        "statePath": "/otc_medications",
        "domain": "generic",
        "preferredPresentation": "cards",
        "primaryColumn": "type"
      },
      "children": []
