      ]
    },
    "prescription_meds_label": {
      "type": "Text",
      "props": {
        "text": "Prescription Medications:",
        "variant": "label"
      },
      "children": []
    },
    "prescription_meds_table": {
      "type": "Table",
      "props": {
        "columns": [
          {
            "key": "type",
            "label": "Medication Type"
          },
          {
            "key": "purpose",
            "label": "Purpose"
          }
        ],
        "statePath": "/prescription_medications",
        "domain": "generic",
        "preferredPresentation": "cards",
        "primaryColumn": "type"
      },
      "children": []
