    "lifestyle_card": {
      "type": "Card",
      "props": {},
      "children": [
        "lifestyle_label",
        "lifestyle_list"
      ]
    },
    "lifestyle_label": {
      "type": "Text",
      "props": {
        "text": "Lifestyle Adjustments and Home Remedies:",
        "variant": "label"
      },
      "children": []
    },
    "lifestyle_list": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "lifestyle_item_1",
        "lifestyle_item_2",
        "lifestyle_item_3",
        "lifestyle_item_4"
      ]
    },
    "lifestyle_item_1": {
      "type": "Text",
      "props": {
        "text": "• Minimize Exposure: Stay indoors when pollen counts are high, keep windows closed, use air conditioning with HEPA filters."
      },
      "children": []
    },
    "lifestyle_item_2": {
      "type": "Text",
      "props": {
        "text": "• Nasal Rinsing: Saline nasal rinses (neti pot, squeeze bottle) can clear allergens and mucus from nasal passages."
      },
      "children": []
    },
    "lifestyle_item_3": {
      "type": "Text",
      "props": {
        "text": "• Shower Before Bed: Wash off pollen from hair and skin before sleeping."
      },
      "children": []
    },
    "lifestyle_item_4": {
      "type": "Text",
      "props": {
        "text": "• Wear Sunglasses: Protect eyes from airborne pollen."
      },
      "children": []
    },
    "context_section": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "context_h3",
        "context_card"
      ]
    },
    "context_h3": {
