    "context_text": {
      "type": "Text",
      "props": {
        "text": "This information assumes adults aged 30-45 with no severe pre-existing medical conditions (such as uncontrolled asthma or heart disease) or known allergies to common medications. Always consult a healthcare professional for personalized diagnosis and treatment."
      },
      "children": []
